use anyhow::Result;
use cudarc::driver::CudaSlice;
use cudarc::driver::DevicePtr;
use cudarc::driver::DevicePtrMut;

use crate::ffi;
use crate::tensor::DeviceContext;
use crate::tensor::DeviceMatrix;
use crate::tensor::DeviceVec;
use crate::tensor::HiddenStates;

/// Embedding lookup reading token_id from decode_meta[0] (CUDA Graph safe)
pub fn embedding_decode_into(
    ctx: &DeviceContext,
    embed: &DeviceMatrix,
    token_id: &CudaSlice<u32>,
    out: &mut DeviceVec,
) -> Result<()> {
    assert_eq!(embed.cols, out.len);

    let (embed_ptr, _ge) = embed.data.device_ptr(&ctx.stream);
    let (token_ptr, _gt) = token_id.device_ptr(&ctx.stream);
    let (out_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);

    let result = unsafe {
        ffi::embedding_decode_cuda(
            embed_ptr as *const ffi::Half,
            token_ptr as *const u32,
            out_ptr as *mut ffi::Half,
            embed.cols as i32,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;

    Ok(())
}

/// Slice-level batched embedding gather: `out[r] = table[ids[r]]` for `rows`
/// rows of `table.cols`. Same kernel as [`embedding_batch`], for callers whose
/// output lives in a persistent decode arena (also reused as the per-token
/// rope-table row gather — a bit-exact row copy).
pub fn embedding_rows_into(
    ctx: &DeviceContext,
    table: &DeviceMatrix,
    ids: &CudaSlice<u32>,
    rows: usize,
    out: &mut CudaSlice<half::bf16>,
) -> Result<()> {
    anyhow::ensure!(rows > 0, "embedding_rows needs positive rows");
    anyhow::ensure!(
        ids.len() >= rows && out.len() >= rows * table.cols,
        "embedding_rows buffers too small: ids {}, out {} for {rows}x{}",
        ids.len(),
        out.len(),
        table.cols
    );
    let (e_ptr, _ge) = table.data.device_ptr(&ctx.stream);
    let (t_ptr, _gt) = ids.device_ptr(&ctx.stream);
    let (o_ptr, _go) = out.device_ptr_mut(&ctx.stream);
    let result = unsafe {
        ffi::embedding_batched_cuda(
            e_ptr as *const ffi::Half,
            t_ptr as *const u32,
            o_ptr as *mut ffi::Half,
            table.cols as i32,
            rows as i32,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;
    Ok(())
}

/// Batched embedding lookup
pub fn embedding_batch(
    ctx: &DeviceContext,
    embed: &DeviceMatrix,
    token_ids_gpu: &CudaSlice<u32>,
    out: &mut HiddenStates,
) -> Result<()> {
    let (e_ptr, _ge) = embed.data.device_ptr(&ctx.stream);
    let (t_ptr, _gt) = token_ids_gpu.device_ptr(&ctx.stream);
    let (o_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);

    let result = unsafe {
        ffi::embedding_batched_cuda(
            e_ptr as *const ffi::Half,
            t_ptr as *const u32,
            o_ptr as *mut ffi::Half,
            embed.cols as i32,
            out.seq_len as i32,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;

    Ok(())
}

/// Vocab-sharded batched embedding lookup for tensor-parallel models.
///
/// Tokens outside `[vocab_start, vocab_start + part_vocab_size)` write zeros;
/// callers should all-reduce `out` across ranks to recover the full embedding.
pub fn embedding_batch_vocab_shard(
    ctx: &DeviceContext,
    embed: &DeviceMatrix,
    token_ids_gpu: &CudaSlice<u32>,
    out: &mut HiddenStates,
    vocab_start: u32,
    part_vocab_size: u32,
) -> Result<()> {
    let (e_ptr, _ge) = embed.data.device_ptr(&ctx.stream);
    let (t_ptr, _gt) = token_ids_gpu.device_ptr(&ctx.stream);
    let (o_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);

    let result = unsafe {
        ffi::embedding_batched_vocab_shard_cuda(
            e_ptr as *const ffi::Half,
            t_ptr as *const u32,
            o_ptr as *mut ffi::Half,
            embed.cols as i32,
            out.seq_len as i32,
            vocab_start,
            part_vocab_size,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use half::bf16;

    use super::*;

    /// The vectorized row-copy path (hidden % 8 == 0) must be bit-exact
    /// against a host-side gather — it is a pure copy.
    #[test]
    fn embedding_batch_vectorized_path_is_bit_exact() {
        let ctx = DeviceContext::new().expect("create CUDA context");
        let hidden_size = 2560; // production Qwen3 width -> vec4 path
        let vocab = 64;
        let seq_len = 33; // not a multiple of the block count on purpose
        let embed_host: Vec<bf16> = (0..vocab * hidden_size)
            .map(|i| bf16::from_f32((((i % 509) as f32) - 254.0) * 0.01))
            .collect();
        let embed = DeviceMatrix::from_host(&ctx, &embed_host, vocab, hidden_size).expect("embed");
        let ids: Vec<u32> = (0..seq_len).map(|i| ((i * 31) % vocab) as u32).collect();
        let token_ids = ctx.stream.clone_htod(&ids).expect("token ids");
        let mut out = HiddenStates::zeros(&ctx, hidden_size, seq_len).expect("out");

        embedding_batch(&ctx, &embed, &token_ids, &mut out).expect("embedding");
        let got = ctx.stream.clone_dtoh(&out.data).expect("dtoh");
        ctx.sync().expect("sync");

        for (token, &id) in ids.iter().enumerate() {
            let row = &embed_host[id as usize * hidden_size..(id as usize + 1) * hidden_size];
            let col = &got[token * hidden_size..(token + 1) * hidden_size];
            assert!(
                row.iter().zip(col).all(|(a, b)| a.to_bits() == b.to_bits()),
                "token {token} (id {id}) differs from host gather"
            );
        }
    }

    /// Same contract for the vectorized vocab-shard path, including the
    /// zero-fill of non-local tokens.
    #[test]
    fn embedding_batch_vocab_shard_vectorized_masks_nonlocal_tokens() {
        let ctx = DeviceContext::new().expect("create CUDA context");
        let hidden_size = 16; // multiple of 8 -> vec4 path
        let embed_host: Vec<bf16> = (0..2 * hidden_size)
            .map(|i| bf16::from_f32(i as f32))
            .collect();
        let embed = DeviceMatrix::from_host(&ctx, &embed_host, 2, hidden_size).expect("embed");
        let token_ids = ctx.stream.clone_htod(&[4_u32, 5, 6, 3]).expect("token ids");
        let mut out = HiddenStates::zeros(&ctx, hidden_size, 4).expect("out");

        embedding_batch_vocab_shard(&ctx, &embed, &token_ids, &mut out, 4, 2)
            .expect("embedding shard");
        let got = ctx.stream.clone_dtoh(&out.data).expect("dtoh");
        ctx.sync().expect("sync");

        assert!(
            got[..hidden_size]
                .iter()
                .zip(&embed_host[..hidden_size])
                .all(|(a, b)| a.to_bits() == b.to_bits()),
            "local token 4 must copy row 0"
        );
        assert!(
            got[hidden_size..2 * hidden_size]
                .iter()
                .zip(&embed_host[hidden_size..])
                .all(|(a, b)| a.to_bits() == b.to_bits()),
            "local token 5 must copy row 1"
        );
        assert!(
            got[2 * hidden_size..]
                .iter()
                .all(|v| v.to_bits() == bf16::ZERO.to_bits()),
            "non-local tokens 6 and 3 must be zero-filled"
        );
    }

    #[test]
    fn embedding_batch_vocab_shard_masks_nonlocal_tokens() {
        let ctx = DeviceContext::new().expect("create CUDA context");
        let hidden_size = 3;
        let seq_len = 4;
        let embed_host = vec![
            bf16::from_f32(10.0),
            bf16::from_f32(11.0),
            bf16::from_f32(12.0),
            bf16::from_f32(20.0),
            bf16::from_f32(21.0),
            bf16::from_f32(22.0),
        ];
        let embed = DeviceMatrix::from_host(&ctx, &embed_host, 2, hidden_size).expect("embed");
        let token_ids = ctx.stream.clone_htod(&[4_u32, 5, 6, 4]).expect("token ids");
        let mut out = HiddenStates::zeros(&ctx, hidden_size, seq_len).expect("out");

        embedding_batch_vocab_shard(&ctx, &embed, &token_ids, &mut out, 4, 2)
            .expect("embedding shard");
        let got = ctx.stream.clone_dtoh(&out.data).expect("dtoh");
        ctx.sync().expect("sync");
        let got: Vec<f32> = got.iter().map(|v| v.to_f32()).collect();

        assert_eq!(
            got,
            vec![
                10.0, 11.0, 12.0, 20.0, 21.0, 22.0, 0.0, 0.0, 0.0, 10.0, 11.0, 12.0
            ]
        );
    }
}

use anyhow::Result;
use anyhow::anyhow;
use anyhow::bail;
use cudarc::driver::CudaSlice;
use cudarc::driver::DevicePtr;
use cudarc::driver::DevicePtrMut;

use crate::ffi;
use crate::tensor::Columns;
use crate::tensor::DeviceContext;
use crate::tensor::DeviceVec;
use crate::tensor::HiddenStates;
use crate::tensor::HiddenStatesRef;

/// Batched element-wise add: out = a + b (same shape HiddenStates)
pub fn add_batch(ctx: &DeviceContext, a: &HiddenStates, b: &HiddenStates) -> Result<HiddenStates> {
    let mut out = HiddenStates::zeros(ctx, a.hidden_dim, a.seq_len)?;
    add_batch_into(ctx, a, b, &mut out)?;
    Ok(out)
}

/// Batched element-wise add into pre-allocated output buffer (zero allocation).
pub fn add_batch_into(
    ctx: &DeviceContext,
    a: &HiddenStates,
    b: &HiddenStates,
    out: &mut HiddenStates,
) -> Result<()> {
    assert_eq!(a.hidden_dim, b.hidden_dim);
    assert_eq!(a.seq_len, b.seq_len);
    assert_eq!(out.hidden_dim, a.hidden_dim);
    assert_eq!(out.seq_len, a.seq_len);

    let n = a.hidden_dim * a.seq_len;
    let (a_ptr, _ga) = a.data.device_ptr(&ctx.stream);
    let (b_ptr, _gb) = b.data.device_ptr(&ctx.stream);
    let (out_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);

    let result = unsafe {
        ffi::add_cuda(
            a_ptr as *const ffi::Half,
            b_ptr as *const ffi::Half,
            out_ptr as *mut ffi::Half,
            n as i32,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;

    Ok(())
}

/// Advance the per-row decode tables written by a regular graph replay.
pub fn advance_decode_metadata(
    ctx: &DeviceContext,
    positions: &mut CudaSlice<i32>,
    local_last: &mut CudaSlice<i32>,
    pseudo_last: &mut CudaSlice<i32>,
    kv_chunk: &mut CudaSlice<i32>,
    rows: usize,
    factor: usize,
) -> Result<()> {
    anyhow::ensure!(rows > 0, "advance_decode_metadata: rows must be positive");
    anyhow::ensure!(
        factor > 0,
        "advance_decode_metadata: factor must be positive"
    );
    let pseudo_rows = rows
        .checked_mul(factor)
        .filter(|n| i32::try_from(*n).is_ok())
        .ok_or_else(|| anyhow!("advance_decode_metadata: rows x factor exceeds i32"))?;
    anyhow::ensure!(
        positions.len() >= rows
            && local_last.len() >= rows
            && kv_chunk.len() >= rows
            && pseudo_last.len() >= pseudo_rows,
        "advance_decode_metadata: {rows} rows x {factor} exceeds a table"
    );
    let rows = super::checked_i32(rows, "advance decode metadata rows")?;
    let factor = super::checked_i32(factor, "advance decode metadata factor")?;
    let (positions_ptr, _positions_guard) = positions.device_ptr_mut(&ctx.stream);
    let (local_ptr, _local_guard) = local_last.device_ptr_mut(&ctx.stream);
    let (pseudo_ptr, _pseudo_guard) = pseudo_last.device_ptr_mut(&ctx.stream);
    let (chunk_ptr, _chunk_guard) = kv_chunk.device_ptr_mut(&ctx.stream);
    let result = unsafe {
        ffi::advance_decode_metadata_cuda(
            positions_ptr as *mut i32,
            local_ptr as *mut i32,
            pseudo_ptr as *mut i32,
            chunk_ptr as *mut i32,
            rows,
            factor,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;
    Ok(())
}

/// Element-wise add of `n` bf16 elements into a pre-allocated output
/// (`out = a + b`). Slice-level twin of [`add_batch_into`] — same kernel —
/// for callers whose buffers live in a persistent decode arena rather than
/// owned `HiddenStates`.
pub fn add_into(
    ctx: &DeviceContext,
    a: &CudaSlice<half::bf16>,
    b: &CudaSlice<half::bf16>,
    n: usize,
    out: &mut CudaSlice<half::bf16>,
) -> Result<()> {
    if a.len() < n || b.len() < n || out.len() < n {
        return Err(anyhow!(
            "add_into buffers too small for n={n}: a {}, b {}, out {}",
            a.len(),
            b.len(),
            out.len()
        ));
    }
    let (a_ptr, _ga) = a.device_ptr(&ctx.stream);
    let (b_ptr, _gb) = b.device_ptr(&ctx.stream);
    let (out_ptr, _go) = out.device_ptr_mut(&ctx.stream);
    let result = unsafe {
        ffi::add_cuda(
            a_ptr as *const ffi::Half,
            b_ptr as *const ffi::Half,
            out_ptr as *mut ffi::Half,
            n as i32,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;
    Ok(())
}

/// `out = bf16(shared + bf16(scale * routed))`.
///
/// The intermediate BF16 narrowing matches vLLM's CUDA MoE path, which
/// scales the reduced routed output in place before adding the shared expert.
pub fn add_scaled_bf16_into(
    ctx: &DeviceContext,
    routed: &CudaSlice<half::bf16>,
    scale: f32,
    shared: &CudaSlice<half::bf16>,
    n: usize,
    out: &mut CudaSlice<half::bf16>,
) -> Result<()> {
    if !scale.is_finite() {
        return Err(anyhow!("add_scaled_bf16_into scale must be finite"));
    }
    if routed.len() < n || shared.len() < n || out.len() < n {
        return Err(anyhow!(
            "add_scaled_bf16_into buffers too small for n={n}: routed {}, shared {}, out {}",
            routed.len(),
            shared.len(),
            out.len()
        ));
    }
    let (routed_ptr, _routed_guard) = routed.device_ptr(&ctx.stream);
    let (shared_ptr, _shared_guard) = shared.device_ptr(&ctx.stream);
    let (out_ptr, _out_guard) = out.device_ptr_mut(&ctx.stream);
    let result = unsafe {
        ffi::add_scaled_bf16_cuda(
            routed_ptr as *const ffi::Half,
            scale,
            shared_ptr as *const ffi::Half,
            out_ptr as *mut ffi::Half,
            n as i32,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;
    Ok(())
}

/// In-place scaled add into a row range of `out`: out[row_offset..] += scale * delta.
pub fn scaled_add_rows_into(
    ctx: &DeviceContext,
    delta: &HiddenStates,
    scale: f32,
    out: &mut HiddenStates,
    row_offset: usize,
) -> Result<()> {
    assert!(
        scale.is_finite(),
        "scaled_add_rows_into scale must be finite"
    );
    assert_eq!(
        delta.seq_len, out.seq_len,
        "delta seq_len {} != out seq_len {}",
        delta.seq_len, out.seq_len
    );
    assert!(
        row_offset + delta.hidden_dim <= out.hidden_dim,
        "row range [{}..{}) exceeds out hidden_dim {}",
        row_offset,
        row_offset + delta.hidden_dim,
        out.hidden_dim
    );

    let (delta_ptr, _gd) = delta.data.device_ptr(&ctx.stream);
    let (out_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);
    let result = unsafe {
        ffi::scaled_add_rows_cuda(
            delta_ptr as *const ffi::Half,
            scale,
            out_ptr as *mut ffi::Half,
            out.hidden_dim as i32,
            row_offset as i32,
            delta.hidden_dim as i32,
            delta.seq_len as i32,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;

    Ok(())
}

/// In-place scaled add into a row range of a contiguous token range in `out`.
pub fn scaled_add_rows_token_range_into(
    ctx: &DeviceContext,
    delta: &HiddenStates,
    scale: f32,
    out: &mut HiddenStates,
    row_offset: usize,
    token_offset: usize,
) -> Result<()> {
    assert!(
        scale.is_finite(),
        "scaled_add_rows_token_range_into scale must be finite"
    );
    assert!(
        row_offset + delta.hidden_dim <= out.hidden_dim,
        "row range [{}..{}) exceeds out hidden_dim {}",
        row_offset,
        row_offset + delta.hidden_dim,
        out.hidden_dim
    );
    assert!(
        token_offset + delta.seq_len <= out.seq_len,
        "token range [{}..{}) exceeds out seq_len {}",
        token_offset,
        token_offset + delta.seq_len,
        out.seq_len
    );

    let (delta_ptr, _gd) = delta.data.device_ptr(&ctx.stream);
    let (out_base, _go) = out.data.device_ptr_mut(&ctx.stream);
    let out_ptr =
        out_base + (token_offset * out.hidden_dim * std::mem::size_of::<half::bf16>()) as u64;
    let result = unsafe {
        ffi::scaled_add_rows_cuda(
            delta_ptr as *const ffi::Half,
            scale,
            out_ptr as *mut ffi::Half,
            out.hidden_dim as i32,
            row_offset as i32,
            delta.hidden_dim as i32,
            delta.seq_len as i32,
            crate::tensor::active_cu_stream(ctx),
        )
    };
    result.result()?;

    Ok(())
}

