pub fn copy_hidden_rows_into(
    ctx: &DeviceContext,
    src: &HiddenStates,
    dst: &mut HiddenStates,
    row_offset: usize,
) -> Result<()> {
    assert_eq!(
        src.seq_len, dst.seq_len,
        "copy_hidden_rows_into seq_len mismatch: src {}, dst {}",
        src.seq_len, dst.seq_len
    );
    copy_hidden_rows_raw_into(
        ctx,
        &src.data,
        src.hidden_dim,
        &mut dst.data,
