1	use anyhow::Result;
2	use anyhow::anyhow;
3	use anyhow::ensure;
4	use cudarc::driver::CudaSlice;
5	use cudarc::driver::DevicePtr;
6	use cudarc::driver::DevicePtrMut;
7	
8	use crate::ffi;
9	use crate::tensor::DeviceContext;
10	use crate::tensor::DeviceVec;
11	use crate::tensor::HiddenStates;
12	use crate::tensor::HiddenStatesRef;
13	
14	/// One non-greedy row of a batched sampling call.
15	///
16	/// `temperature` must be > 0 and `top_p` in (0, 1] — greedy rows
17	/// (`temperature <= 0` or `top_k == 1`) belong on the argmax path.
18	/// `top_k <= 0` means disabled. `min_p` in [0, 1); `0.0` means disabled —
19	/// `gpu_sample_batch_into` partitions min_p rows into their own pass, so
20	/// callers may mix freely.
21	#[derive(Clone, Copy, Debug)]
22	pub struct BatchSamplingRow {
23	    /// Row index into the logits arena.
24	    pub row: usize,
25	    pub temperature: f32,
26	    pub top_k: i32,
27	    pub top_p: f32,
28	    pub min_p: f32,
29	}
30	
31	/// Device buffers for `gpu_sample_batch_into`, sized for `max_rows` x `vocab`.
32	pub struct BatchSamplingScratch {
33	    probs: CudaSlice<f32>,
34	    row_indices: CudaSlice<i32>,
35	    temperature: CudaSlice<f32>,
36	    top_k: CudaSlice<i32>,
37	    top_p: CudaSlice<f32>,
38	    min_p: CudaSlice<f32>,
39	    topk_row_states: CudaSlice<u8>,
40	    valid: CudaSlice<u8>,
41	    out: CudaSlice<i32>,
42	    softmax_workspace: CudaSlice<u8>,
43	    max_rows: usize,
44	    vocab: usize,
45	}
46	
47	impl BatchSamplingScratch {
48	    pub fn new(ctx: &DeviceContext, max_rows: usize, vocab: usize) -> Result<Self> {
49	        ensure!(
50	            max_rows > 0 && vocab > 0,
51	            "batch sampling scratch requires max_rows > 0 and vocab > 0"
52	        );
53	        // OnlineSoftmax vocab-splitting path: batch x ceil(vocab / 8192)
54	        // partials of {f32 max, f32 denominator}, plus alignment slack.
55	        let softmax_workspace_bytes = max_rows * vocab.div_ceil(8192) * 8 + 256;
56	        let topk_row_states_bytes = unsafe { ffi::gpu_sample_topk_renorm_row_states_bytes_cuda() };
57	        let alloc = |n: usize| -> Result<CudaSlice<f32>> {
58	            ctx.stream
59	                .alloc_zeros(n)
60	                .map_err(|e| anyhow!("batch sampling scratch alloc failed: {e}"))
61	        };
62	        Ok(Self {
63	            probs: alloc(max_rows * vocab)?,
64	            row_indices: ctx.stream.alloc_zeros(max_rows)?,
65	            temperature: alloc(max_rows)?,
66	            top_k: ctx.stream.alloc_zeros(max_rows)?,
67	            top_p: alloc(max_rows)?,
68	            min_p: alloc(max_rows)?,
69	            topk_row_states: ctx.stream.alloc_zeros(topk_row_states_bytes)?,
70	            valid: ctx.stream.alloc_zeros(max_rows)?,
71	            out: ctx.stream.alloc_zeros(max_rows)?,
72	            softmax_workspace: ctx.stream.alloc_zeros(softmax_workspace_bytes)?,
73	            max_rows,
74	            vocab,
75	        })
76	    }
77	}
78	
79	/// Batched temperature/top-k/top-p sampling: gathers the requested bf16 arena
80	/// rows, then runs FlashInfer's batched softmax + sampling — three kernel
81	/// launches, one sync, and one D2H for the whole batch.
82	///
83	/// `seed` must be fresh per decode step (one philox seed per call; rows
84	/// decorrelate through the philox subsequence). Returns one token per row, in
85	/// `rows` order.
86	///
87	/// min_p rows run as their own pass: if they shared a call, every row would
88	/// ride the min_p kernel, whose u-scaling (`u * q`) and survivor predicate
89	/// differ from the fused fast path — a min_p == 0 row could then sample a
90	/// different token than it would alone. Partitioning here (not in callers)
91	/// keeps "min_p == 0 rows take the original path" true for every caller, at
92	/// the cost of a second full pass (gather + softmax + sample, own sync) only
93	/// when a batch actually mixes.
94	pub fn gpu_sample_batch_into(
95	    ctx: &DeviceContext,
96	    logits: HiddenStatesRef<'_>,
97	    rows: &[BatchSamplingRow],
98	    seed: u64,
99	    scratch: &mut BatchSamplingScratch,
100	) -> Result<Vec<u32>> {
101	    if rows.iter().all(|r| r.min_p > 0.0) || rows.iter().all(|r| r.min_p <= 0.0) {
102	        return sample_uniform_batch_into(ctx, logits, rows, seed, scratch);
103	    }
104	    let (minp, plain): (Vec<BatchSamplingRow>, Vec<BatchSamplingRow>) =
105	        rows.iter().copied().partition(|r| r.min_p > 0.0);
106	    let plain_tokens = sample_uniform_batch_into(ctx, logits, &plain, seed, scratch)?;
107	    // Distinct philox key for the second pass: both passes restart their
108	    // subsequences at 0, so reusing `seed` would hand minp row i the same
109	    // uniform stream as plain row i and correlate their tokens.
110	    let minp_seed = seed ^ 0x9E37_79B9_7F4A_7C15;
111	    let minp_tokens = sample_uniform_batch_into(ctx, logits, &minp, minp_seed, scratch)?;
112	    let mut plain_it = plain_tokens.into_iter();
113	    let mut minp_it = minp_tokens.into_iter();
114	    Ok(rows
115	        .iter()
116	        .map(|r| {
117	            if r.min_p > 0.0 {
118	                minp_it.next().expect("minp token per minp row")
119	            } else {
120	                plain_it.next().expect("plain token per plain row")
121	            }
122	        })
123	        .collect())
124	}
125	
126	/// One homogeneous FlashInfer pass (rows are all-min_p or all-plain).
127	fn sample_uniform_batch_into(
128	    ctx: &DeviceContext,
129	    logits: HiddenStatesRef<'_>,
130	    rows: &[BatchSamplingRow],
131	    seed: u64,
132	    scratch: &mut BatchSamplingScratch,
133	) -> Result<Vec<u32>> {
134	    let n = rows.len();
135	    ensure!(n > 0, "batch sampling requires at least one row");
136	    ensure!(
137	        n <= scratch.max_rows,
138	        "batch sampling scratch too small: {n} rows > capacity {}",
139	        scratch.max_rows
140	    );
141	    ensure!(
142	        logits.hidden_dim == scratch.vocab,
143	        "batch sampling vocab mismatch: logits {} vs scratch {}",
144	        logits.hidden_dim,
145	        scratch.vocab
146	    );
147	
148	    let mut row_indices = Vec::with_capacity(n);
149	    let mut temperature = Vec::with_capacity(n);
150	    let mut top_k = Vec::with_capacity(n);
151	    let mut top_p = Vec::with_capacity(n);
152	    let mut min_p = Vec::with_capacity(n);
153	    let mut has_top_k_filter = false;
154	    let mut has_top_p_filter = false;
155	    let mut has_min_p_filter = false;
156	    for r in rows {
157	        ensure!(
158	            r.row < logits.seq_len,
159	            "batch sampling row {} out of arena range {}",
160	            r.row,
161	            logits.seq_len
162	        );
163	        ensure!(
164	            r.temperature > 0.0 && r.temperature.is_finite(),
165	            "batch sampling temperature {} must be finite and > 0 (greedy rows take the argmax path)",
166	            r.temperature
167	        );
168	        ensure!(
169	            r.top_p > 0.0 && r.top_p <= 1.0,
170	            "batch sampling top_p {} must be in (0, 1]",
171	            r.top_p
172	        );
173	        ensure!(
174	            (0.0..1.0).contains(&r.min_p) && r.min_p.is_finite(),
175	            "batch sampling min_p {} must be in [0, 1)",
176	            r.min_p
177	        );
178	        row_indices.push(i32::try_from(r.row)?);
179	        temperature.push(r.temperature);
180	        // FlashInfer reads top_k as u32; "disabled" is any k >= vocab.
181	        let vocab = i32::try_from(scratch.vocab)?;
182	        let clamped_top_k = if r.top_k > 0 && r.top_k < vocab {
183	            has_top_k_filter = true;
184	            r.top_k
185	        } else {
186	            vocab
187	        };
188	        top_k.push(clamped_top_k);
189	        if r.top_p < 1.0 {
190	            has_top_p_filter = true;
191	        }
192	        top_p.push(r.top_p);
193	        if r.min_p > 0.0 {
194	            has_min_p_filter = true;
195	        }
196	        min_p.push(r.min_p);
197	    }
198	    ctx.stream
199	        .memcpy_htod(&row_indices, &mut scratch.row_indices)?;
200	    ctx.stream
201	        .memcpy_htod(&temperature, &mut scratch.temperature)?;
202	    ctx.stream.memcpy_htod(&top_k, &mut scratch.top_k)?;
203	    ctx.stream.memcpy_htod(&top_p, &mut scratch.top_p)?;
204	    if has_min_p_filter {
205	        ctx.stream.memcpy_htod(&min_p, &mut scratch.min_p)?;
206	    }
207	
208	    {
209	        let softmax_workspace_bytes = scratch.softmax_workspace.len();
210	        let (logits_ptr, _gl) = logits.data.device_ptr(&ctx.stream);
211	        let (indices_ptr, _gi) = scratch.row_indices.device_ptr(&ctx.stream);
212	        let (probs_ptr, _gp) = scratch.probs.device_ptr_mut(&ctx.stream);
213	        let (temp_ptr, _gt) = scratch.temperature.device_ptr(&ctx.stream);
214	        let (top_k_ptr, _gk) = scratch.top_k.device_ptr(&ctx.stream);
215	        let (top_p_ptr, _gtp) = scratch.top_p.device_ptr(&ctx.stream);
216	        let (min_p_ptr, _gmp) = scratch.min_p.device_ptr(&ctx.stream);
217	        // topk_row_states is only read on the min_p pipeline; the fast path
218	        // hands the kernel a null instead of borrowing the buffer.
219	        let row_states = if has_min_p_filter {
220	            Some(scratch.topk_row_states.device_ptr_mut(&ctx.stream))
221	        } else {
222	            None
223	        };
224	        let row_states_ptr = row_states.as_ref().map_or(0, |(ptr, _guard)| *ptr);
225	        let (valid_ptr, _gv) = scratch.valid.device_ptr_mut(&ctx.stream);
226	        let (out_ptr, _go) = scratch.out.device_ptr_mut(&ctx.stream);
227	        let (ws_ptr, _gw) = scratch.softmax_workspace.device_ptr_mut(&ctx.stream);
228	
229	        let err = unsafe {
230	            ffi::gpu_sample_batch_flashinfer_cuda(
231	                logits_ptr as *const ffi::Half,
232	                indices_ptr as *const i32,
233	                probs_ptr as *mut f32,
234	                temp_ptr as *const f32,
235	                top_k_ptr as *const i32,
236	                top_p_ptr as *const f32,
237	                if has_min_p_filter {
238	                    min_p_ptr as *const f32
239	                } else {
240	                    std::ptr::null()
241	                },
242	                row_states_ptr as *mut u8,
243	                valid_ptr as *mut u8,
244	                out_ptr as *mut i32,
245	                ws_ptr as *mut u8,
246	                softmax_workspace_bytes,
247	                n as i32,
248	                scratch.vocab as i32,
249	                i32::from(has_top_k_filter),
250	                i32::from(has_top_p_filter),
251	                seed,
252	                0,
253	                crate::tensor::active_cu_stream(ctx),
254	            )
255	        };
256	        ensure!(
257	            err == 0,
258	            "batch sampling kernel failed with error {err}{}",
259	            crate::ops::ffi_exception_message(err)
260	        );
261	    }
262	
263	    let out = ctx
264	        .stream
265	        .clone_dtoh(&scratch.out)
266	        .map_err(|e| anyhow!("D2H batch sample read failed: {e}"))?;
267	    let valid = ctx
268	        .stream
269	        .clone_dtoh(&scratch.valid)
270	        .map_err(|e| anyhow!("D2H batch sample valid read failed: {e}"))?;
271	    ctx.sync()?;
272	
273	    let mut tokens = Vec::with_capacity(n);
274	    for (i, r) in rows.iter().enumerate() {
275	        ensure!(
276	            valid[i] != 0,
277	            "batch sampling produced no valid token for arena row {} (probs failed to cover u)",
278	            r.row
279	        );
280	        ensure!(
281	            out[i] >= 0 && (out[i] as usize) < scratch.vocab,
282	            "batch sampling token {} for arena row {} out of vocab range {}",
283	            out[i],
284	            r.row,
285	            scratch.vocab
286	        );
287	        tokens.push(out[i] as u32);
288	    }
289	    Ok(tokens)
290	}
