275	__global__ void repeat_f32_rows_for_reduce_scatter_kernel(
276	    const float *__restrict__ local,
277	    float *__restrict__ repeated,
278	    int local_elems,
279	    int world_size) {
280	  int total = local_elems * world_size;
281	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
