288	// ============================================================================
289	// SiLU-mul from separate gate/up buffers: out = silu(gate) * up
290	// Matches Triton silu_mul_kernel rounding: silu computed in f32,
291	// cast to bf16, then multiplied with up in bf16→f32.
292	// ============================================================================
293	
294	__global__ void silu_mul_kernel(
295	    const __nv_bfloat16 *__restrict__ gate,
296	    const __nv_bfloat16 *__restrict__ up,
297	    __nv_bfloat16 *__restrict__ out,
298	    int n) {
299	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
300	       idx < n;
301	       idx += gridDim.x * blockDim.x) {
302	    float g = __bfloat162float(gate[idx]);
303	    float u = __bfloat162float(up[idx]);
304	    float silu_g = g / (1.0f + expf(-g));
305	    // Match Triton rounding: silu result cast to bf16 before multiply
306	    out[idx] = __float2bfloat16(__bfloat162float(__float2bfloat16(silu_g)) * u);
307	  }
308	}
309	
310	// ============================================================================
311	// GELU-tanh-mul from separate gate/up buffers: out = gelu_tanh(gate) * up
312	// (Gemma 4 MLP, hidden_activation "gelu_pytorch_tanh" — the tanh
313	// approximation, not erf). Matches the HF op sequence rounding: act_fn(gate)
314	// materializes a bf16 tensor before the elementwise multiply, so the
315	// activation is computed in f32, cast to bf16, then multiplied in f32 and
316	// rounded once more.
317	// ============================================================================
318	
319	// `gate` and `up` are column bands of row-major activations, `cols` wide and
320	// each at its own row stride, so both may sit in one fused gate|up row; the
321	// output is contiguous and `n = rows * cols`.
322	__global__ void gelu_tanh_mul_kernel(
323	    const __nv_bfloat16 *__restrict__ gate,
324	    const __nv_bfloat16 *__restrict__ up,
325	    __nv_bfloat16 *__restrict__ out,
326	    int cols,
327	    int gate_stride,
328	    int up_stride,
329	    int n) {
330	  // sqrt(2/pi), the gelu_pytorch_tanh constant.
331	  const float kSqrt2OverPi = 0.7978845608028654f;
332	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
333	       idx < n;
334	       idx += gridDim.x * blockDim.x) {
335	    int row = idx / cols;
336	    int col = idx - row * cols;
337	    float g = __bfloat162float(gate[(int64_t)row * gate_stride + col]);
338	    float u = __bfloat162float(up[(int64_t)row * up_stride + col]);
339	    float inner = kSqrt2OverPi * (g + 0.044715f * g * g * g);
340	    float gelu_g = 0.5f * g * (1.0f + tanhf(inner));
341	    out[idx] = __float2bfloat16(__bfloat162float(__float2bfloat16(gelu_g)) * u);
342	  }
343	}
344	
345	// ============================================================================
346	// In-place final-logit softcap: buf[i] = bf16(cap * tanh(f32(buf[i]) / cap)).
347	// Gemma 4 declares final_logit_softcapping (30.0 at every published size) and
348	// applies it to the LM head output in the compute dtype; f32 internal with a
349	// single rounding matches the reference's bf16 elementwise chain.
350	// ============================================================================
351	
352	__global__ void softcap_bf16_kernel(
353	    __nv_bfloat16 *__restrict__ buf,
354	    float cap,
355	    int n) {
356	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
357	       idx < n;
358	       idx += gridDim.x * blockDim.x) {
359	    float x = __bfloat162float(buf[idx]);
360	    buf[idx] = __float2bfloat16(cap * tanhf(x / cap));
361	  }
362	}
