364	// ============================================================================
365	// In-place logit suppression. Ids reach here only through the Rust
366	// `SuppressIds` type, which refuses any id outside the head at upload.
367	// ============================================================================
368	
369	__global__ void suppress_logits_bf16_kernel(
370	    __nv_bfloat16 *__restrict__ logits,
371	    const uint32_t *__restrict__ ids,
372	    int vocab,
373	    int id_count,
374	    int total) {
375	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
376	       idx < total;
377	       idx += gridDim.x * blockDim.x) {
378	    int row = idx / id_count;
379	    int id_slot = idx % id_count;
380	    logits[(size_t)row * vocab + ids[id_slot]] =
381	        __float2bfloat16(-CUDART_INF_F);
382	  }
383	}
