500	// Vectorized variant of the vocab-sharded lookup; same layout contract as
501	// embedding_batched_vec4_kernel, with non-local tokens writing zero vectors.
502	__global__ void embedding_batched_vocab_shard_vec4_kernel(
503	    const uint4 *__restrict__ embed,
504	    const uint32_t *__restrict__ token_ids,
505	    uint4 *__restrict__ out,
506	    int hidden_vec, int seq_len, uint32_t vocab_start,
507	    uint32_t part_vocab_size) {
508	  const int token = blockIdx.x;
509	  if (token >= seq_len) {
510	    return;
511	  }
512	  const uint32_t token_id = __ldg(&token_ids[token]);
513	  uint4 *__restrict__ dst = out + (size_t)token * hidden_vec;
514	  if (token_id >= vocab_start && token_id < vocab_start + part_vocab_size) {
515	    const uint4 *__restrict__ src =
516	        embed + (size_t)(token_id - vocab_start) * hidden_vec;
517	    for (int v = blockIdx.y * blockDim.x + threadIdx.x; v < hidden_vec;
518	         v += gridDim.y * blockDim.x) {
519	      dst[v] = src[v];
520	    }
521	  } else {
522	    const uint4 zero = make_uint4(0u, 0u, 0u, 0u);
523	    for (int v = blockIdx.y * blockDim.x + threadIdx.x; v < hidden_vec;
524	         v += gridDim.y * blockDim.x) {
525	      dst[v] = zero;
526	    }
527	  }
528	}
