800	    return CUDA_ERROR_INVALID_VALUE;
801	  }
802	  int block = 256;
803	  int grid = (hidden_dim + block - 1) / block;
804	  accumulate_bf16_token_scaled_to_f32_kernel<<<grid, block, 0, stream>>>(
805	      token, scale, out, hidden_dim, token_idx, seq_len);
806	  return map_cuda_error(cudaGetLastError());
