820	CUresult silu_mul_triton_aot_cuda(
821	    const __nv_bfloat16 *gate, const __nv_bfloat16 *up,
822	    __nv_bfloat16 *out, int n, cudaStream_t stream) {
823	  int block = 256;
824	  int grid = (n + block - 1) / block;
