953	    embedding_batched_vec4_kernel<<<grid, EMBEDDING_VEC4_BLOCK, 0, stream>>>(
954	        reinterpret_cast<const uint4 *>(embed), token_ids,
955	        reinterpret_cast<uint4 *>(out), hidden_vec, seq_len);
956	    return map_cuda_error(cudaGetLastError());
957	  }
958	  int block = 256;
959	  int total = hidden_size * seq_len;
960	  int grid = (total + block - 1) / block;
961	  embedding_batched_kernel<<<grid, block, 0, stream>>>(embed, token_ids, out, hidden_size, seq_len);
962	  return map_cuda_error(cudaGetLastError());
