12	namespace {
13	
14	constexpr int GATHER_CAST_BLOCK = 256;
15	constexpr int GATHER_CAST_ELEMS_PER_THREAD = 8;
16	
17	// Gather rows of a bf16 logits arena into a compact f32 buffer.
18	// grid = (ceil(vocab / (BLOCK * ELEMS)), n_rows); row_indices == nullptr means identity.
19	__global__ void gather_cast_logits_f32_kernel(const __nv_bfloat16* __restrict__ logits,
20	                                              const int* __restrict__ row_indices,
21	                                              float* __restrict__ out, int vocab_size) {
22	  int compact_row = blockIdx.y;
23	  int src_row = row_indices == nullptr ? compact_row : row_indices[compact_row];
24	  const __nv_bfloat16* src = logits + static_cast<size_t>(src_row) * vocab_size;
25	  float* dst = out + static_cast<size_t>(compact_row) * vocab_size;
26	
27	  int base = (blockIdx.x * GATHER_CAST_BLOCK + threadIdx.x) * GATHER_CAST_ELEMS_PER_THREAD;
28	#pragma unroll
29	  for (int j = 0; j < GATHER_CAST_ELEMS_PER_THREAD; ++j) {
30	    int i = base + j;
31	    if (i < vocab_size) {
32	      dst[i] = __bfloat162float(src[i]);
33	    }
34	  }
35	}
36	
37	}  // namespace
38	
39	// Batched temperature/top-k/top-p sampling over a bf16 logits arena.
40	//
41	// Three launches for the whole batch: gather+cast (bf16 -> f32), FlashInfer
42	// OnlineSoftmax (per-row temperature, vocab-splitting strategy for the
43	// small-batch x large-vocab decode regime), then one FlashInfer sampling kernel
44	// (Sampling/TopP/TopKTopP depending on the row params). One philox seed per
45	// call; rows decorrelate through the philox subsequence (= row index), so the
46	// caller must supply a fresh seed per decode step.
47	//
48	// top_k_arr entries must be pre-clamped to [1, vocab_size] when top-k is used;
49	// temperature_arr entries must be > 0 — greedy rows belong on the argmax path,
50	// not here.
51	// Workspace for the radix top-k renorm used on the min_p pipeline; same
52	// layout contract as flashinfer_top1_row_states_bytes_cuda.
53	extern "C" size_t gpu_sample_topk_renorm_row_states_bytes_cuda() {
54	  return flashinfer_radix_row_states_bytes();
55	}
56	
57	// min_p_arr enables the min_p pipeline: (optional) top-k renorm, (optional)
58	// top-p renorm, then FlashInfer's MinPSamplingFromProb with the per-row
59	// thresholds. min_p_arr == nullptr keeps the original fused single-kernel
60	// paths bit-for-bit (the fast path).
61	//
62	// Per-request seeds deliberately do NOT go through FlashInfer's `seed_arr`:
63	// these kernels read `seed_arr[0]` (one seed for the whole batch) and fold
64	// `blockIdx.x` into the philox subsequence, so a request's stream would
65	// change with its position in the batch. Seeded rows are instead sampled as
66	// their own n_rows=1 calls by the Rust layer, with the request seed and step
67	// mixed into `seed` — blockIdx is then always 0 and replay is independent of
68	// batch composition.
69	extern "C" int gpu_sample_batch_flashinfer_cuda(
70	    const __nv_bfloat16* logits, const int* row_indices, float* probs_scratch,
71	    const float* temperature_arr, const int* top_k_arr, const float* top_p_arr,
72	    const float* min_p_arr, uint8_t* topk_row_states_scratch,
73	    uint8_t* valid_scratch, int* output, void* softmax_workspace,
74	    size_t softmax_workspace_bytes, int n_rows, int vocab_size, int has_top_k_filter,
75	    int has_top_p_filter, uint64_t seed, uint64_t offset, cudaStream_t stream) {
76	  PEGAINFER_FFI_GUARD_BEGIN
77	  dim3 gather_grid(
78	      (vocab_size + GATHER_CAST_BLOCK * GATHER_CAST_ELEMS_PER_THREAD - 1) /
79	          (GATHER_CAST_BLOCK * GATHER_CAST_ELEMS_PER_THREAD),
80	      n_rows);
81	  gather_cast_logits_f32_kernel<<<gather_grid, GATHER_CAST_BLOCK, 0, stream>>>(
82	      logits, row_indices, probs_scratch, vocab_size);
83	  cudaError_t err = cudaGetLastError();
84	  if (err != cudaSuccess) {
85	    return static_cast<int>(err);
86	  }
87	
88	  // In-place: phase 2 of both OnlineSoftmax strategies is an elementwise
89	  // read-then-write of the same index.
90	  err = flashinfer::sampling::OnlineSoftmax<float>(
91	      probs_scratch, probs_scratch, n_rows, vocab_size, const_cast<float*>(temperature_arr),
92	      /*temperature_val=*/1.0f, softmax_workspace, softmax_workspace_bytes,
93	      /*enable_pdl=*/false, stream);
94	  if (err != cudaSuccess) {
95	    return static_cast<int>(err);
96	  }
97	
98	  bool* valid = reinterpret_cast<bool*>(valid_scratch);
99	  if (min_p_arr != nullptr) {
100	    if (has_top_k_filter) {
101	      auto* row_states =
102	          reinterpret_cast<flashinfer::sampling::RadixRowState*>(topk_row_states_scratch);
103	      if (row_states == nullptr) {
104	        return static_cast<int>(cudaErrorInvalidValue);
105	      }
106	      // In-place: the renorm kernels reduce a threshold first, then rewrite
107	      // each element from its own index.
108	      err = flashinfer::sampling::RadixTopKRenormProbMultiCTA<float, int>(
109	          probs_scratch, probs_scratch, const_cast<int*>(top_k_arr), n_rows,
110	          /*top_k_val=*/0, vocab_size, row_states, /*deterministic=*/false, stream);
111	      if (err != cudaSuccess) {
112	        return static_cast<int>(err);
113	      }
114	    }
115	    if (has_top_p_filter) {
116	      err = flashinfer::sampling::TopPRenormProb<float>(
117	          probs_scratch, probs_scratch, const_cast<float*>(top_p_arr), n_rows,
118	          /*top_p_val=*/0.0f, vocab_size, stream);
119	      if (err != cudaSuccess) {
120	        return static_cast<int>(err);
121	      }
122	    }
123	    err = flashinfer::sampling::MinPSamplingFromProb<float, int>(
124	        probs_scratch, const_cast<float*>(min_p_arr), output, valid,
125	        /*indices=*/nullptr, n_rows, /*min_p_val=*/0.0f, vocab_size,
126	        /*deterministic=*/true, /*seed_arr=*/nullptr, seed, /*offset_arr=*/nullptr, offset,
127	        stream);
128	    return static_cast<int>(err);
129	  }
130	  if (has_top_k_filter) {
131	    err = flashinfer::sampling::TopKTopPSamplingFromProb<float, int>(
132	        probs_scratch, const_cast<int*>(top_k_arr), const_cast<float*>(top_p_arr), output, valid,
133	        /*indices=*/nullptr, n_rows, /*top_k_val=*/0, /*top_p_val=*/0.0f, vocab_size,
134	        /*deterministic=*/true, /*seed_arr=*/nullptr, seed, /*offset_arr=*/nullptr, offset,
135	        stream);
136	  } else if (has_top_p_filter) {
137	    err = flashinfer::sampling::TopPSamplingFromProb<float, int>(
138	        probs_scratch, output, valid, /*indices=*/nullptr, const_cast<float*>(top_p_arr), n_rows,
139	        /*top_p_val=*/1.0f, vocab_size, /*deterministic=*/true, /*seed_arr=*/nullptr, seed,
140	        /*offset_arr=*/nullptr, offset, stream);
141	  } else {
142	    err = flashinfer::sampling::SamplingFromProb<float, int>(
143	        probs_scratch, output, valid, /*indices=*/nullptr, n_rows, vocab_size,
144	        /*deterministic=*/true, /*seed_arr=*/nullptr, seed, /*offset_arr=*/nullptr, offset,
145	        stream);
146	  }
147	  return static_cast<int>(err);
148	  PEGAINFER_FFI_GUARD_END(-1)
149	}
