9	// Element-wise add: out = a + b (bf16, computed in f32)
10	// ============================================================================
11	
12	__global__ void add_kernel(
13	    const __nv_bfloat16 *__restrict__ a,
14	    const __nv_bfloat16 *__restrict__ b,
15	    __nv_bfloat16 *__restrict__ out,
16	    int n) {
17	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
18	       idx < n;
19	       idx += gridDim.x * blockDim.x) {
20	    float va = __bfloat162float(a[idx]);
21	    float vb = __bfloat162float(b[idx]);
22	    out[idx] = __float2bfloat16(va + vb);
23	  }
24	}
25	
26	__global__ void add_scaled_bf16_kernel(
27	    const __nv_bfloat16 *__restrict__ routed,
28	    float scale,
29	    const __nv_bfloat16 *__restrict__ shared,
30	    __nv_bfloat16 *__restrict__ out,
31	    int n) {
32	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
33	       idx < n;
34	       idx += gridDim.x * blockDim.x) {
35	    // Match vLLM's two BF16 operations: scale the routed output in place,
36	    // then add the shared expert.
37	    __nv_bfloat16 scaled = __float2bfloat16(
38	        __bfloat162float(routed[idx]) * scale);
39	    out[idx] = __float2bfloat16(
40	        __bfloat162float(shared[idx]) + __bfloat162float(scaled));
41	  }
42	}
