44	__global__ void scaled_add_rows_kernel(
45	    const __nv_bfloat16 *__restrict__ delta,
46	    float scale,
47	    __nv_bfloat16 *__restrict__ out,
48	    int out_hidden_dim,
49	    int row_offset,
50	    int rows,
51	    int seq_len) {
52	  for (int token = blockIdx.y * blockDim.y + threadIdx.y;
53	       token < seq_len;
54	       token += gridDim.y * blockDim.y) {
55	    for (int row = blockIdx.x * blockDim.x + threadIdx.x;
56	         row < rows;
57	         row += gridDim.x * blockDim.x) {
58	      int delta_idx = token * rows + row;
59	      int out_idx = token * out_hidden_dim + row_offset + row;
60	      float base = __bfloat162float(out[out_idx]);
61	      float add = __bfloat162float(delta[delta_idx]) * scale;
62	      out[out_idx] = __float2bfloat16(base + add);
63	    }
64	  }
65	}
