67	__global__ void gather_hidden_tokens_kernel(
68	    const __nv_bfloat16 *__restrict__ input,
69	    const int *__restrict__ token_indices,
70	    __nv_bfloat16 *__restrict__ out,
71	    int hidden_dim,
72	    int token_count,
73	    int input_seq_len) {
74	  int total = hidden_dim * token_count;
75	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
76	       idx < total;
77	       idx += gridDim.x * blockDim.x) {
78	    int token = idx / hidden_dim;
79	    int row = idx % hidden_dim;
80	    int src_token = token_indices[token];
81	    if (src_token < 0 || src_token >= input_seq_len) {
82	      continue;
83	    }
84	    out[idx] = input[(size_t)src_token * hidden_dim + row];
85	  }
86	}
