88	__global__ void copy_hidden_rows_kernel(
89	    const __nv_bfloat16 *__restrict__ src,
90	    __nv_bfloat16 *__restrict__ dst,
91	    int src_hidden_dim,
92	    int dst_hidden_dim,
93	    int row_offset,
94	    int rows,
95	    int seq_len) {
96	  int total = rows * seq_len;
97	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
98	       idx < total;
99	       idx += gridDim.x * blockDim.x) {
100	    int token = idx / rows;
101	    int row = idx % rows;
102	    dst[(size_t)token * dst_hidden_dim + row_offset + row] =
103	        src[(size_t)token * src_hidden_dim + row];
104	  }
