162	__global__ void scaled_add_rows_indexed_kernel(
163	    const __nv_bfloat16 *__restrict__ delta,
164	    float scale,
165	    const int *__restrict__ token_indices,
166	    __nv_bfloat16 *__restrict__ out,
167	    int out_hidden_dim,
168	    int row_offset,
169	    int rows,
170	    int token_count,
171	    int out_seq_len) {
172	  for (int token = blockIdx.y * blockDim.y + threadIdx.y;
173	       token < token_count;
174	       token += gridDim.y * blockDim.y) {
175	    int out_token = token_indices[token];
176	    if (out_token < 0 || out_token >= out_seq_len) {
177	      continue;
178	    }
179	    for (int row = blockIdx.x * blockDim.x + threadIdx.x;
180	         row < rows;
181	         row += gridDim.x * blockDim.x) {
182	      int delta_idx = token * rows + row;
183	      // out_token * out_hidden_dim overflows i32 for large row pools (the K3
184	      // paged-KV slab exceeds 2^31 elements), so the element index is size_t.
185	      size_t out_idx =
186	          (size_t)out_token * out_hidden_dim + row_offset + row;
187	      float base = __bfloat162float(out[out_idx]);
188	      float add = __bfloat162float(delta[delta_idx]) * scale;
189	      out[out_idx] = __float2bfloat16(base + add);
190	    }
