210	    for (int row = blockIdx.x * blockDim.x + threadIdx.x;
211	         row < rows;
212	         row += gridDim.x * blockDim.x) {
213	      int src_idx = token * rows + row;
214	      // out_token * out_hidden_dim overflows i32 for large row pools (the K3
215	      // paged-KV slab exceeds 2^31 elements), so the element index is size_t.
216	      size_t out_idx =
217	          (size_t)out_token * out_hidden_dim + row_offset + row;
218	      out[out_idx] = src[src_idx];
219	    }
220	  }
221	}
