386	// In-place multiply by a host scalar: buf[i] = bf16(f32(buf[i]) * scale).
387	// Serves Gemma 4's per-layer layer_scalar, a [1] weight the model reads to
388	// the host at load; f32 compute with a single rounding matches HF's bf16
389	// elementwise multiply.
390	// ============================================================================
391	
392	__global__ void scale_bf16_kernel(
393	    __nv_bfloat16 *__restrict__ buf,
394	    float scale,
395	    int n) {
396	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
397	       idx < n;
398	       idx += gridDim.x * blockDim.x) {
399	    buf[idx] = __float2bfloat16(__bfloat162float(buf[idx]) * scale);
400	  }
401	}
