404	// Embedding lookup: out = embed[token_id, :]
405	// Reads token_id from token_id[0] (CUDA Graph safe).
406	// ============================================================================
407	
408	__global__ void embedding_decode_kernel(
409	    const __nv_bfloat16 *__restrict__ embed,
410	    const uint32_t *__restrict__ token_id,
411	    __nv_bfloat16 *__restrict__ out,
412	    int hidden_size) {
413	  uint32_t token_idx = __ldg(&token_id[0]);
414	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
415	       idx < hidden_size;
416	       idx += gridDim.x * blockDim.x) {
417	    out[idx] = embed[(size_t)token_idx * hidden_size + idx];
418	  }
419	}
