421	// ============================================================================
422	// Batched embedding lookup: out[:, i] = embed[token_ids[i], :]
423	// Column-major output: [hidden_size, seq_len].
424	// ============================================================================
425	
426	__global__ void embedding_batched_kernel(
427	    const __nv_bfloat16 *__restrict__ embed,
428	    const uint32_t *__restrict__ token_ids,
429	    __nv_bfloat16 *__restrict__ out,
430	    int hidden_size, int seq_len) {
431	  int total = hidden_size * seq_len;
432	  for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
433	       idx < total;
434	       idx += gridDim.x * blockDim.x) {
435	    int token_offset = idx / hidden_size;
436	    int dim_offset = idx % hidden_size;
437	    uint32_t token_id = token_ids[token_offset];
438	    out[idx] = embed[(size_t)token_id * hidden_size + dim_offset];
439	  }
440	}
441	
442	// Vectorized batched embedding lookup: grid.x indexes the token, grid.y
443	// splits the row into block-wide segments of 16-byte vectors, token id
444	// loaded once per block. The scalar kernel above moves 2 bytes per thread
445	// per access with a div+mod and a token_ids reload per element, which caps
446	// it near a quarter of DRAM bandwidth; the vectorized row copy streams at
447	// full width, and the 2D grid keeps enough blocks in flight at small token
448	// counts (decode) that the launch floor does not regress. Requires
449	// hidden_size % 8 == 0 and 16-byte-aligned base pointers — the launcher
450	// falls back to the scalar kernel otherwise.
451	__global__ void embedding_batched_vec4_kernel(
452	    const uint4 *__restrict__ embed,
453	    const uint32_t *__restrict__ token_ids,
454	    uint4 *__restrict__ out,
455	    int hidden_vec, int seq_len) {
456	  const int token = blockIdx.x;
457	  if (token >= seq_len) {
458	    return;
459	  }
460	  const uint32_t token_id = __ldg(&token_ids[token]);
461	  const uint4 *__restrict__ src = embed + (size_t)token_id * hidden_vec;
462	  uint4 *__restrict__ dst = out + (size_t)token * hidden_vec;
463	  for (int v = blockIdx.y * blockDim.x + threadIdx.x; v < hidden_vec;
464	       v += gridDim.y * blockDim.x) {
465	    dst[v] = src[v];
466	  }
467	}
