531	static const int ADVANCE_DECODE_METADATA_BLOCK = 32;
532	
533	__global__ void advance_decode_metadata_kernel(
534	    int *__restrict__ positions,
535	    int *__restrict__ local_last,
536	    int *__restrict__ pseudo_last,
537	    int *__restrict__ kv_chunk,
