829	// Eight elements a thread through 16-byte loads and stores, the same
830	// per-element arithmetic as the scalar form, so the two round alike; the
831	// launcher picks it whenever every band and row is eight elements aligned.
832	__global__ void gelu_tanh_mul_vec8_kernel(
833	    const __nv_bfloat16 *__restrict__ gate,
834	    const __nv_bfloat16 *__restrict__ up,
835	    __nv_bfloat16 *__restrict__ out,
836	    int cols8,
837	    int gate_stride,
838	    int up_stride,
839	    int n8) {
840	  const float kSqrt2OverPi = 0.7978845608028654f;
841	  union Pack8 {
842	    uint4 u;
843	    __nv_bfloat16 h[8];
844	  };
845	  for (int v = blockIdx.x * blockDim.x + threadIdx.x;
846	       v < n8;
847	       v += gridDim.x * blockDim.x) {
848	    int row = v / cols8;
849	    int col = (v - row * cols8) * 8;
850	    Pack8 g, u, o;
851	    g.u = *reinterpret_cast<const uint4 *>(gate + (int64_t)row * gate_stride + col);
852	    u.u = *reinterpret_cast<const uint4 *>(up + (int64_t)row * up_stride + col);
853	#pragma unroll
854	    for (int i = 0; i < 8; i++) {
855	      float gv = __bfloat162float(g.h[i]);
856	      float uv = __bfloat162float(u.h[i]);
857	      float inner = kSqrt2OverPi * (gv + 0.044715f * gv * gv * gv);
858	      float gelu_g = 0.5f * gv * (1.0f + tanhf(inner));
859	      o.h[i] = __float2bfloat16(__bfloat162float(__float2bfloat16(gelu_g)) * uv);
860	    }
861	    *reinterpret_cast<uint4 *>(out + (int64_t)v * 8) = o.u;
862	  }
863	}
864	
865	CUresult gelu_tanh_mul_cuda(
866	    const __nv_bfloat16 *gate, const __nv_bfloat16 *up,
867	    __nv_bfloat16 *out, int cols, int gate_stride, int up_stride, int n,
868	    cudaStream_t stream) {
869	  if (cols <= 0 || gate_stride < cols || up_stride < cols || n % cols != 0) {
870	    return CUDA_ERROR_INVALID_VALUE;
871	  }
872	  int block = 256;
873	  bool vec8 = cols % 8 == 0 && gate_stride % 8 == 0 && up_stride % 8 == 0 &&
874	              (reinterpret_cast<uintptr_t>(gate) & 15) == 0 &&
875	              (reinterpret_cast<uintptr_t>(up) & 15) == 0 &&
876	              (reinterpret_cast<uintptr_t>(out) & 15) == 0;
877	  if (vec8) {
878	    int n8 = n / 8;
879	    int grid = n8 / block + (n8 % block != 0);
880	    gelu_tanh_mul_vec8_kernel<<<grid, block, 0, stream>>>(
881	        gate, up, out, cols / 8, gate_stride, up_stride, n8);
882	  } else {
883	    int grid = n / block + (n % block != 0);
884	    gelu_tanh_mul_kernel<<<grid, block, 0, stream>>>(
885	        gate, up, out, cols, gate_stride, up_stride, n);
886	  }
887	  return map_cuda_error(cudaGetLastError());
888	}
