926	  embedding_decode_kernel<<<grid, block, 0, stream>>>(embed, token_id, out, hidden_size);
927	  return map_cuda_error(cudaGetLastError());
928	}
929	
930	// Whether the vectorized row-copy embedding kernels can serve this call:
931	// whole 16-byte vectors per row and 16-byte-aligned base pointers. Row
932	// offsets stay aligned because every row is a whole number of vectors.
933	static bool embedding_vec4_ok(
934	    const void *embed, const void *out, int hidden_size) {
935	  return hidden_size % 8 == 0 &&
936	         ((reinterpret_cast<uintptr_t>(embed) |
937	           reinterpret_cast<uintptr_t>(out)) & 15) == 0;
938	}
939	
940	// Measured on H100 with the 2D grid (seq 128/2048/10000, bs 1/32): 128
941	// threads edges out 256 by ~2% at 10k tokens and is level elsewhere — more
942	// row segments per token hide the gather latency slightly better.
943	static const int EMBEDDING_VEC4_BLOCK = 128;
944	
945	CUresult embedding_batched_cuda(
946	    const __nv_bfloat16 *embed, const uint32_t *token_ids,
947	    __nv_bfloat16 *out, int hidden_size, int seq_len, cudaStream_t stream) {
948	  if (embedding_vec4_ok(embed, out, hidden_size)) {
949	    int hidden_vec = hidden_size / 8;
950	    int row_segs =
951	        (hidden_vec + EMBEDDING_VEC4_BLOCK - 1) / EMBEDDING_VEC4_BLOCK;
952	    dim3 grid(seq_len, row_segs);
953	    embedding_batched_vec4_kernel<<<grid, EMBEDDING_VEC4_BLOCK, 0, stream>>>(
954	        reinterpret_cast<const uint4 *>(embed), token_ids,
955	        reinterpret_cast<uint4 *>(out), hidden_vec, seq_len);
956	    return map_cuda_error(cudaGetLastError());
957	  }
958	  int block = 256;
959	  int total = hidden_size * seq_len;
960	  int grid = (total + block - 1) / block;
961	  embedding_batched_kernel<<<grid, block, 0, stream>>>(embed, token_ids, out, hidden_size, seq_len);
962	  return map_cuda_error(cudaGetLastError());
963	}
964	
965	CUresult embedding_batched_vocab_shard_cuda(
966	    const __nv_bfloat16 *embed, const uint32_t *token_ids,
967	    __nv_bfloat16 *out, int hidden_size, int seq_len,
968	    uint32_t vocab_start, uint32_t part_vocab_size, cudaStream_t stream) {
969	  if (embedding_vec4_ok(embed, out, hidden_size)) {
970	    int hidden_vec = hidden_size / 8;
971	    int row_segs =
972	        (hidden_vec + EMBEDDING_VEC4_BLOCK - 1) / EMBEDDING_VEC4_BLOCK;
973	    dim3 grid(seq_len, row_segs);
974	    embedding_batched_vocab_shard_vec4_kernel<<<
975	        grid, EMBEDDING_VEC4_BLOCK, 0, stream>>>(
976	        reinterpret_cast<const uint4 *>(embed), token_ids,
977	        reinterpret_cast<uint4 *>(out), hidden_vec, seq_len,
978	        vocab_start, part_vocab_size);
979	    return map_cuda_error(cudaGetLastError());
980	  }
981	  int block = 256;
982	  int total = hidden_size * seq_len;
983	  int grid = (total + block - 1) / block;
984	  embedding_batched_vocab_shard_kernel<<<grid, block, 0, stream>>>(
985	      embed, token_ids, out, hidden_size, seq_len, vocab_start, part_vocab_size);
986	  return map_cuda_error(cudaGetLastError());
987	}
