989	CUresult advance_decode_metadata_cuda(
990	    int *positions, int *local_last, int *pseudo_last, int *kv_chunk,
991	    int rows, int factor, cudaStream_t stream) {
992	  if (positions == nullptr || local_last == nullptr || pseudo_last == nullptr ||
993	      kv_chunk == nullptr || rows <= 0 || factor <= 0 || rows > INT_MAX / factor) {
994	    return CUDA_ERROR_INVALID_VALUE;
995	  }
996	  int block = ADVANCE_DECODE_METADATA_BLOCK;
997	  int grid = 1 + (rows - 1) / block;
998	  advance_decode_metadata_kernel<<<grid, block, 0, stream>>>(
999	      positions, local_last, pseudo_last, kv_chunk, rows, factor);
