1	//! Device gate for the Gemma 4 elementwise additions in
2	//! csrc/shared/elementwise.cu: gelu_tanh_mul and scale_bf16.
3	//!
4	//! Manual gate: CI compiles this but never runs it. Run on a GPU box with
5	//! PEGAINFER_REQUIRE_GPU=1, which turns a missing device into a failure
6	//! rather than a skip.
7	//!
8	//! Scope note: on the bf16 grid the tanh approximation and the erf GELU are
9	//! numerically indistinguishable (their worst-case gap is below half a bf16
10	//! ulp), and the 2-ulp tolerance that absorbs device-vs-host tanh drift also
11	//! absorbs the kernel's intermediate bf16 round — this gate pins the formula
12	//! (a SiLU swap, a dropped cubic term), not the variant or the op-sequence
13	//! rounding. The variant question rides on the Gemma 4 layer oracle against
14	//! the HF fixture.
15	
16	mod common;
17	
18	use half::bf16;
19	use pegainfer_kernels::ops::gelu_tanh_mul_batch_into;
20	use pegainfer_kernels::ops::scale_bf16_in_place;
21	use pegainfer_kernels::tensor::HiddenStates;
22	
23	/// Mirrors the kernel arithmetic: activation in f32, cast to bf16, then
24	/// multiplied in f32 and rounded once more.
25	fn host_gelu_tanh_mul(g: f32, u: f32) -> f32 {
26	    let inner = 0.797_884_6_f32 * (g + 0.044_715_f32 * g * g * g);
27	    let gelu_g = 0.5_f32 * g * (1.0_f32 + inner.tanh());
28	    let gelu_bf16 = bf16::from_f32(gelu_g).to_f32();
29	    bf16::from_f32(gelu_bf16 * u).to_f32()
30	}
31	
32	#[test]
33	fn gelu_tanh_mul_matches_host_reference() {
34	    let Some(ctx) = common::device_or_skip() else {
35	        return;
36	    };
37	    let ctx = &ctx;
38	    // x = 2.0 is the constant-sensitive case: dropping the 0.044715 cubic
39	    // term shifts gelu(2) by ~1.7%, and at up 2.0 the product moves 0.0625 —
40	    // twice the 0.031 tolerance there; x = 1.0 separates GELU from a SiLU
41	    // swap (0.8412 vs 0.7311). Negatives cover the branch where GELU
42	    // saturates toward zero.
43	    let gate_vals = [-8.0f32, -2.0, -1.0, -0.5, 0.0, 0.5, 1.0, 2.0, 8.0];
44	    let up_vals = [2.0f32, -1.5, 1.0, 3.0, 2.0, -2.0, 1.0, 2.0, 2.0];
45	
46	    let gate_host: Vec<bf16> = gate_vals.iter().map(|&v| bf16::from_f32(v)).collect();
47	    let up_host: Vec<bf16> = up_vals.iter().map(|&v| bf16::from_f32(v)).collect();
48	    let n = gate_vals.len();
49	    let gate = HiddenStates::from_host(ctx, &gate_host, n, 1).expect("gate H2D");
50	    let up = HiddenStates::from_host(ctx, &up_host, n, 1).expect("up H2D");
51	    let mut out = HiddenStates::zeros(ctx, n, 1).expect("out alloc");
52	
53	    gelu_tanh_mul_batch_into(ctx, &gate, &up, &mut out).expect("gelu launch");
54	
55	    let got = out.to_host(ctx).expect("out D2H");
56	    for (i, (&g, &u)) in gate_vals.iter().zip(&up_vals).enumerate() {
57	        let e = host_gelu_tanh_mul(g, u);
58	        // Two bf16 ulp relative, floored for near-zero expectations: host
59	        // tanh and device tanhf may differ in the last f32 ulp, which after
60	        // the bf16 round can move one grid step on boundary values.
61	        let tol = (e.abs() * 0.008).max(0.02);
62	        assert!(
63	            (got[i] - e).abs() <= tol,
64	            "gelu_tanh_mul[{i}] (gate {g}, up {u}): got {}, expected {e} \
65	             (tolerance {tol})",
66	            got[i]
67	        );
68	    }
69	}
70	
71	/// Powers of two times small integers stay exactly representable in bf16
72	/// under a power-of-two scale, so the assertion is bitwise equality — an
73	/// off-by-one bound that skips the last element cannot pass.
74	#[test]
75	#[allow(clippy::float_cmp)]
76	fn scale_bf16_scales_exactly() {
77	    let Some(ctx) = common::device_or_skip() else {
78	        return;
79	    };
80	    let ctx = &ctx;
81	    let vals = [-4.0f32, -1.5, -0.5, 0.0, 0.25, 1.0, 3.0, 8.0];
82	    let host: Vec<bf16> = vals.iter().map(|&v| bf16::from_f32(v)).collect();
83	    let mut buf = HiddenStates::from_host(ctx, &host, vals.len(), 1).expect("buf H2D");
84	
85	    scale_bf16_in_place(ctx, &mut buf, 2.0).expect("scale launch");
86	
87	    let got = buf.to_host(ctx).expect("buf D2H");
88	    for (i, &v) in vals.iter().enumerate() {
89	        assert_eq!(
